/* Hidden attribute safeguard */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #2b3a42;
  --color-card: #f4f0ea;
  --color-plant-green: #4f8f00;
  --color-accent-blue: #2a75d3;
  --color-accent-blue-hover: #1f5cb0;
  --color-accent-blue-active: #154382;
  --color-alert-red: #d9383a;
  --color-text-main: #1f2d3d;
  --color-text-muted: #536271;
  --color-meter-bg: #d8dee4;
  --font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text-main);
  font-family: var(--font-family);
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background-color: var(--color-card);
  border-radius: 12px;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.35);
  width: 100%;
  max-width: 400px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.card-header {
  text-align: center;
}

.card-header h1 {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--color-text-main);
}

.card-header .subtitle {
  font-size: 1rem;
  color: var(--color-text-muted);
}

.plant-display {
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #e2ded5;
  border-radius: 8px;
  border: 2px solid #ccc6b8;
  padding: 12px;
}

#plantCanvas {
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  width: 160px;
  height: 160px;
  display: block;
}

.thirsty-alert {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--color-alert-red);
  min-height: 1.6em;
  display: flex;
  align-items: center;
  justify-content: center;
  text-transform: uppercase;
  letter-spacing: 1px;
  visibility: hidden;
}

.thirsty-alert.visible {
  visibility: visible;
}

.meter-section {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.meter-label-row {
  display: flex;
  justify-content: space-between;
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text-main);
}

.meter-track {
  width: 100%;
  height: 22px;
  background-color: var(--color-meter-bg);
  border-radius: 11px;
  overflow: hidden;
  border: 2px solid #bbc4cc;
}

.meter-fill {
  height: 100%;
  background-color: var(--color-accent-blue);
  transition: width 0.15s ease-out, background-color 0.3s ease;
}

.meter-fill.warning {
  background-color: var(--color-alert-red);
}

.actions {
  width: 100%;
}

.btn-water {
  width: 100%;
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: 700;
  color: #ffffff;
  background-color: var(--color-accent-blue);
  border: none;
  border-radius: 8px;
  padding: 14px 20px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  box-shadow: 0 4px 6px rgba(42, 117, 211, 0.25);
  transition: background-color 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
}

.btn-water:hover {
  background-color: var(--color-accent-blue-hover);
  box-shadow: 0 6px 10px rgba(31, 92, 176, 0.35);
}

.btn-water:focus-visible {
  outline: 3px solid #f9a03f;
  outline-offset: 3px;
}

.btn-water:active {
  background-color: var(--color-accent-blue-active);
  transform: translateY(2px);
  box-shadow: 0 2px 4px rgba(21, 67, 130, 0.3);
}

.card-footer {
  width: 100%;
  border-top: 1px solid #e0dbce;
  padding-top: 14px;
  display: flex;
  justify-content: center;
}

.stat-box {
  text-align: center;
}

.stat-label {
  display: block;
  font-size: 0.9rem;
  color: var(--color-text-muted);
  margin-bottom: 2px;
}

.stat-value {
  font-size: 1.3rem;
  font-weight: 700;
  color: var(--color-text-main);
}

document.addEventListener('DOMContentLoaded', () => {
  const DRAIN_DURATION_MS = 2 * 60 * 1000; // 2 minutes (120,000 ms)
  let moisture = 100;
  let wateredCount = 0;
  let lastTimestamp = performance.now();

  // DOM Elements
  const canvas = document.getElementById('plantCanvas');
  const ctx = canvas.getContext('2d');
  const thirstyMessage = document.getElementById('thirstyMessage');
  const moistureFill = document.getElementById('moistureFill');
  const moistureValue = document.getElementById('moistureValue');
  const moistureBar = document.getElementById('moistureBar');
  const waterBtn = document.getElementById('waterBtn');
  const waterCount = document.getElementById('waterCount');

  // Disable antialiasing for crisp pixel art
  ctx.imageSmoothingEnabled = false;

  // 16x16 Pixel Art Matrices
  // . = transparent
  // P = pot (#c1693c)
  // D = dark pot border (#8b3e1b)
  // S = soil (#543621)
  // G = green leaf (#4f8f00)
  // L = light leaf highlight (#7cc728)
  // B = brown wilted leaf (#8a6237)
  // Y = pale wilted leaf (#ab884c)

  const healthyMatrix = [
    '................',
    '......LL........',
    '.....LGGG.......',
    '....GGGGGL......',
    '....GG.GGG......',
    '...LGG..GG.LL...',
    '..GGGG..GGGGGL..',
    '..GGG...GGGGGG..',
    '...GG....GGGG...',
    '....G...GGGG....',
    '...DDDDDDDDDD...',
    '...DPSSSSSSD...',
    '....PSSSSSS.....',
    '....PSSSSSS.....',
    '....PPPPPPP.....',
    '.....DDDDD......'
  ];

  const wiltedMatrix = [
    '................',
    '................',
    '................',
    '................',
    '......B.........',
    '....YBBB..Y.....',
    '....BBBB.BBB....',
    '...YBB..BBBY....',
    '..BBB...BBBB....',
    '.BBB.....BB.....',
    '...DDDDDDDDDD...',
    '...DPSSSSSSD...',
    '....PSSSSSS.....',
    '....PSSSSSS.....',
    '....PPPPPPP.....',
    '.....DDDDD......'
  ];

  const colorMap = {
    'P': '#c1693c',
    'D': '#8b3e1b',
    'S': '#543621',
    'G': '#4f8f00',
    'L': '#7cc728',
    'B': '#8a6237',
    'Y': '#ab884c'
  };

  function drawPixelArt(matrix) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const pixelSize = canvas.width / 16; // 8x8 per pixel block

    for (let row = 0; row < 16; row++) {
      const line = matrix[row];
      for (let col = 0; col < 16; col++) {
        const char = line[col];
        if (colorMap[char]) {
          ctx.fillStyle = colorMap[char];
          ctx.fillRect(col * pixelSize, row * pixelSize, pixelSize, pixelSize);
        }
      }
    }
  }

  function updateUI() {
    const isWilted = moisture < 30;
    const displayPercent = Math.max(0, Math.round(moisture));

    // Update bar width and accessibility attributes
    moistureFill.style.width = `${displayPercent}%`;
    moistureValue.textContent = `${displayPercent}%`;
    moistureBar.setAttribute('aria-valuenow', displayPercent);

    // Thirsty & wilted state (<30%)
    if (isWilted) {
      thirstyMessage.classList.add('visible');
      moistureFill.classList.add('warning');
      drawPixelArt(wiltedMatrix);
    } else {
      thirstyMessage.classList.remove('visible');
      moistureFill.classList.remove('warning');
      drawPixelArt(healthyMatrix);
    }

    waterCount.textContent = wateredCount;
  }

  function waterPlant() {
    moisture = 100;
    wateredCount += 1;
    lastTimestamp = performance.now();
    updateUI();
  }

  // Linear moisture drain loop
  function tick(currentTimestamp) {
    const elapsed = currentTimestamp - lastTimestamp;
    lastTimestamp = currentTimestamp;

    // Drain linearly: 100% over DRAIN_DURATION_MS (2 minutes)
    const drainRate = 100 / DRAIN_DURATION_MS;
    moisture = Math.max(0, moisture - (elapsed * drainRate));

    updateUI();
    requestAnimationFrame(tick);
  }

  // Event listeners
  waterBtn.addEventListener('click', waterPlant);

  // Initial render & loop start
  updateUI();
  requestAnimationFrame(tick);
});
